  HC-12 VCC  -> Arduino 5V
  HC-12 GND  -> Arduino GND
  HC-12 TXD  -> Arduino D10 (RX)
  HC-12 RXD  -> Arduino D11 (TX)
  HC-12 SET  -> Arduino D12 (Güç ayarı yapmak için)
*/

#include <SoftwareSerial.h>

// HC-12 ile haberleşmek için sanal seri port (RX, TX)
SoftwareSerial HC12(10, 11); 

const int SET_PIN = 12;

void setup() {
  Serial.begin(9600);
  HC12.begin(9600);

  pinMode(SET_PIN, OUTPUT);

  Serial.println("Hedef Cihaz Baslatiliyor...");

  // 1. ADIM: HC-12'yi Ayar (AT Command) Moduna Al
  digitalWrite(SET_PIN, LOW);
  delay(200); // Modülün ayar moduna girmesi için bekle

  // 2. ADIM: Gücü Düşür (Kör Etmeyi / Sinyal Boğulmasını Önlemek İçin)
  // AT+P8 (Varsayılan 100mW) çok güçlüdür, RTL-SDR'ı sağır eder.
  // AT+P4 (Yaklaşık 6mW) seçiyoruz. Hem yeterince uzağa gider hem sağır etmez.
  HC12.print("AT+P4");
  delay(200);

  // (İsteğe Bağlı) HC-12 Varsayılan Kanal 1'dir (433.4 MHz).
  // RTL-SDR'ımız 432-434 MHz aralığını dinlediği için bu kanal mükemmeldir.
  // Kanalı sabitlemek isterseniz: HC12.print("AT+C001"); delay(200);

  // 3. ADIM: Ayar modundan çık ve Normal Çalışma Moduna (Şeffaf Mod) geç
  digitalWrite(SET_PIN, HIGH);
  delay(200);

  Serial.println("HC-12 Guc Ayari AT+P4 (6mW) Olarak Ayarlandi!");
  Serial.println("Merkez Sinyali (Beacon) Yayinlanmaya Basliyor...");
}

